-- c001-v009: Και–θα–κατατρομαχθούν δυνατοί-σου Θαιμάν, ώστε να–εξολοθρευθεί– κάθε-άνδρας από–όρους Ησαύ με–σφαγή.
-- c001-v010: Από–βία αδελφού-σου Ιακώβ θα–σε–σκεπάσει αισχύνη, και–θα–εξολοθρευθείς για–πάντα.
-- c001-v011: Στ–την-ημέρα που–στεκόσουν απέναντι, στ–την-ημέρα που–αιχμαλώτιζαν ξένοι δύναμή-αυτού, και–αλλοδαποί μπήκαν [ketiv] πύλες-αυτού, και–για– Ιερουσαλήμ έριξαν κλήρο, και– εσύ σαν–ένας από–αυτούς.
-- c001-v012: Και–μη– βλέπεις στ–την-ημέρα– αδελφού-σου στ–την-ημέρα δυστυχίας-αυτού, και–μη– χαίρεσαι για–υιούς– Ιούδα στ–την-ημέρα απώλειας-αυτών· και–μη– μεγαλύνεις στόμα-σου στ–την-ημέρα θλίψεως.
